import{_ as t,c as a,a2 as l,o as i}from"./chunks/framework.BAVNBlau.js";const S=JSON.parse('{"title":"网页渲染过程","description":"","frontmatter":{},"headers":[],"relativePath":"other/other.md","filePath":"other/other.md"}'),r={name:"other/other.md"};function o(h,e,n,d,s,c){return i(),a("div",null,e[0]||(e[0]=[l('<h1 id="网页渲染过程" tabindex="-1">网页渲染过程 <a class="header-anchor" href="#网页渲染过程" aria-label="Permalink to &quot;网页渲染过程&quot;">​</a></h1><h2 id="url-统一资源定位符" tabindex="-1">URL(统一资源定位符) <a class="header-anchor" href="#url-统一资源定位符" aria-label="Permalink to &quot;URL(统一资源定位符)&quot;">​</a></h2><ul><li>scheme：协议，例如 http、https、ftp 等</li><li>host：主机名， 例如<code>www</code>就是一个主机名</li><li>domain：域名，例如<code>www.baidu.com</code>就是一个域名</li><li>port：端口号，http 默认 80</li><li>path：路径</li><li>query：查询字符串，以键值对形式出现</li><li>fragment：片段，用于定位到某个具体的资源</li></ul><h2 id="dns-解析" tabindex="-1">DNS 解析 <a class="header-anchor" href="#dns-解析" aria-label="Permalink to &quot;DNS 解析&quot;">​</a></h2><p>DNS（域名系统）解析是将域名转换为 IP 地址的过程</p><p>浏览器如何通过域名查询 IP</p><ul><li>浏览器缓存: 浏览器会缓存 DNS 记录一段时间，这个时间就是 DNS 缓存时间（TTL 值），一般来说，DNS 的缓存时间比较短，大部分情况下，DNS 查询都会在浏览器缓存中找到结果。</li><li>操作系统缓存: 浏览器会查询操作系统中的 DNS 缓存，如果操作系统中有缓存，那么浏览器就会直接使用操作系统的 DNS 缓存。</li><li>路由器缓存: 浏览器会查询路由器的 DNS 缓存，如果路由器中有缓存，那么浏览器就会直接使用路由器的 DNS 缓存。</li><li>ISP(互联网服务提供商) DNS 缓存: 浏览器会查询 ISP 的 DNS 缓存，如果 ISP 有缓存，那么浏览器就会直接使用 ISP 的 DNS 缓存。</li><li>根服务器</li></ul>',7)]))}const u=t(r,[["render",o]]);export{S as __pageData,u as default};
